select upper(name) as u, length(name) as l, substr(name, 2, 3) as s, replace(name, 'R', 'r') as r, trim(name) as t, instr(name, 'e') as i, hex(name) as h, quote(email) as q, printf('%s-%d', name, id) as p, abs(score) as a, round(score, 1) as rd, nullif(name, 'Robert') as nu, ifnull(email, 'none') as em, char(65) as ch, unicode(name) as un, random() as rn, likely(id > 1) as lk from users
